#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    // Earliest position of each prefix parity mask; equal masks bound an all-even substring.
    unordered_map<int, int> first;
    first.reserve(s.size() * 2 + 2);
    first[0] = -1;
    int mask = 0, best = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        mask ^= 1 << (s[i] - 'a');
        auto it = first.find(mask);
        if (it != first.end()) best = max(best, i - it->second);
        else first[mask] = i;
    }
    cout << best << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        HashMap<Integer, Integer> first = new HashMap<>();
        first.put(0, -1);
        int mask = 0, best = 0;
        for (int i = 0; i < s.length(); i++) {
            mask ^= 1 << (s.charAt(i) - 'a');
            Integer at = first.get(mask);
            if (at != null) best = Math.max(best, i - at);
            else first.put(mask, i);
        }
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := token()
	first := map[int]int{0: -1}
	mask, best := 0, 0
	for i, c := range s {
		mask ^= 1 << (c - 'a')
		if at, ok := first[mask]; ok {
			best = max(best, i-at)
		} else {
			first[mask] = i
		}
	}
	fmt.Println(best)
}
